-- DAEHAN grade 3 example words batch 6
with words(word,reading,meaning,child_explanation,chars) as (values
('대장','대장','큰창자','소화 기관 가운데 굵고 긴 창자',array['大','腸']),('재식','재식','심어 기름','나무나 작물을 심어 기르는 것',array['栽','植']),('선재','선재','참으로 좋구나','한문에서 좋은 일을 칭찬하며 감탄하는 표현',array['善','哉']),('저명','저명','이름이 널리 알려짐','이름이나 업적이 많은 사람에게 알려진 상태',array['著','名']),('적금','적금','돈을 차곡차곡 모음','일정한 돈을 정기적으로 모아 두는 저축',array['積','金']),('전재','전재','돈과 재물','돈이나 값나가는 재물을 이르는 말',array['錢','財']),('안정','안정','고요하고 편안함','마음이나 상태가 흔들리지 않고 편안한 것',array['安','靜']),('정절','정절','곧고 바른 절개','마음을 굳게 지켜 바른 뜻을 따르는 태도',array['貞','節']),('정화','정화','깨끗하게 함','더러운 것을 없애 깨끗하게 만드는 것',array['淨','化']),('정상','정상','가장 높은 곳','산이나 물체의 맨 꼭대기',array['頂','上']),('제다','제다','여러 가지','여럿이나 많은 것을 이르는 말',array['諸','多']),('제왕','제왕','나라를 다스리는 임금','나라를 다스리는 황제나 왕',array['帝','王']),('종성','종성','종소리','종을 쳤을 때 나는 소리',array['鐘','聲']),('종순','종순','따라서 순종함','말이나 뜻을 따라 거스르지 않는 것',array['從','順']),('주식','주식','술과 음식','술과 음식을 함께 이르는 말',array['酒','食']),('즉금','즉금','바로 지금','바로 이 순간을 뜻하는 말',array['卽','今']),('증조','증조','증조부모를 이르는 말','할아버지나 할머니의 부모 세대를 이르는 말',array['曾','祖']),('증서','증서','사실을 증명하는 문서','어떤 사실이나 권리를 증명하는 문서',array['證','書']),('지엽','지엽','가지와 잎','나무의 가지와 잎을 함께 이르는 말',array['枝','葉']),('지간','지간','그 사이','한문에서 어떤 것과 어떤 것 사이를 나타내는 말',array['之','間']),('지혜','지혜','슬기로운 생각','사물의 이치를 잘 알고 올바르게 판단하는 능력',array['智','慧']),('진력','진력','힘을 다함','할 수 있는 힘을 모두 써서 노력하는 것',array['盡','力'])
), upserted as (insert into public.hanja_words(word,reading,meaning,child_explanation,content_status,source_note) select word,reading,meaning,child_explanation,'PUBLISHED','3급 신규 예시어 보강 6차 · 2026-10-06' from words on conflict(word,reading,meaning) do update set child_explanation=excluded.child_explanation,content_status='PUBLISHED',source_note=excluded.source_note returning id,word,reading,meaning)
insert into public.hanja_word_map(word_id,hanja_id,position) select hw.id,h.id,u.ord::integer from words w join upserted hw on hw.word=w.word and hw.reading=w.reading and hw.meaning=w.meaning cross join lateral unnest(w.chars) with ordinality u(ch,ord) join public.hanja h on h.character=u.ch on conflict do nothing;